102	/// Returns the maximum number of threads that Rayon supports in a single thread pool.
103	///
104	/// If a higher thread count is requested by calling `ThreadPoolBuilder::num_threads` or by setting
105	/// the `RAYON_NUM_THREADS` environment variable, then it will be reduced to this maximum.
106	///
107	/// The value may vary between different targets, and is subject to change in new Rayon versions.
108	pub fn max_num_threads() -> usize {
109	    // We are limited by the bits available in the sleep counter's `AtomicUsize`.
110	    crate::sleep::THREADS_MAX
111	}
