113	/// Returns the number of threads in the current registry. If this
114	/// code is executing within a Rayon thread pool, then this will be
115	/// the number of threads for the thread pool of the current
116	/// thread. Otherwise, it will be the number of threads for the global
117	/// thread pool.
118	///
119	/// This can be useful when trying to judge how many times to split
120	/// parallel work (the parallel iterator traits use this value
121	/// internally for this purpose).
122	///
123	/// # Future compatibility note
124	///
125	/// Note that unless this thread pool was created with a
126	/// builder that specifies the number of threads, then this
127	/// number may vary over time in future versions (see [the
128	/// `num_threads()` method for details][snt]).
129	///
130	/// [snt]: ThreadPoolBuilder::num_threads
131	pub fn current_num_threads() -> usize {
132	    crate::registry::Registry::current_num_threads()
133	}
