280	impl ThreadPoolBuilder {
281	    /// Creates a scoped `ThreadPool` initialized using this configuration.
282	    ///
283	    /// This is a convenience function for building a pool using [`std::thread::scope`]
284	    /// to spawn threads in a [`spawn_handler`].
285	    /// The threads in this pool will start by calling `wrapper`, which should
286	    /// do initialization and continue by calling `ThreadBuilder::run()`.
287	    ///
288	    /// [`spawn_handler`]: Self::spawn_handler()
289	    ///
290	    /// # Examples
291	    ///
292	    /// A scoped pool may be useful in combination with scoped thread-local variables.
293	    ///
294	    /// ```ignore-wasm
295	    /// # use rayon_core as rayon;
296	    ///
297	    /// scoped_tls::scoped_thread_local!(static POOL_DATA: Vec<i32>);
298	    ///
299	    /// fn main() -> Result<(), rayon::ThreadPoolBuildError> {
300	    ///     let pool_data = vec![1, 2, 3];
301	    ///
302	    ///     // We haven't assigned any TLS data yet.
303	    ///     assert!(!POOL_DATA.is_set());
304	    ///
305	    ///     rayon::ThreadPoolBuilder::new()
306	    ///         .build_scoped(
307	    ///             // Borrow `pool_data` in TLS for each thread.
308	    ///             |thread| POOL_DATA.set(&pool_data, || thread.run()),
309	    ///             // Do some work that needs the TLS data.
310	    ///             |pool| pool.install(|| assert!(POOL_DATA.is_set())),
311	    ///         )?;
312	    ///
313	    ///     // Once we've returned, `pool_data` is no longer borrowed.
314	    ///     drop(pool_data);
315	    ///     Ok(())
316	    /// }
317	    /// ```
318	    pub fn build_scoped<W, F, R>(self, wrapper: W, with_pool: F) -> Result<R, ThreadPoolBuildError>
319	    where
320	        W: Fn(ThreadBuilder) + Sync, // expected to call `run()`
321	        F: FnOnce(&ThreadPool) -> R,
322	    {
323	        std::thread::scope(|scope| {
324	            let pool = self
325	                .spawn_handler(|thread| {
326	                    let mut builder = std::thread::Builder::new();
327	                    if let Some(name) = thread.name() {
328	                        builder = builder.name(name.to_string());
329	                    }
330	                    if let Some(size) = thread.stack_size() {
331	                        builder = builder.stack_size(size);
332	                    }
333	                    builder.spawn_scoped(scope, || wrapper(thread))?;
334	                    Ok(())
335	                })
336	                .build()?;
337	            Ok(with_pool(&pool))
338	        })
339	    }
340	}
