764	            ErrorKind::GlobalPoolAlreadyInitialized | ErrorKind::CurrentThreadAlreadyInPool => None,
765	            ErrorKind::IOError(e) => Some(e),
766	        }
767	    }
768	}
769	
770	impl fmt::Display for ThreadPoolBuildError {
771	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
772	        match &self.kind {
773	            ErrorKind::CurrentThreadAlreadyInPool => CURRENT_THREAD_ALREADY_IN_POOL.fmt(f),
774	            ErrorKind::GlobalPoolAlreadyInitialized => GLOBAL_POOL_ALREADY_INITIALIZED.fmt(f),
775	            ErrorKind::IOError(e) => e.fmt(f),
776	        }
777	    }
778	}
779	
780	/// Deprecated in favor of `ThreadPoolBuilder::build_global`.
781	#[deprecated(note = "use `ThreadPoolBuilder::build_global`")]
782	#[expect(deprecated)]
783	pub fn initialize(config: Configuration) -> Result<(), Box<dyn Error>> {
784	    config.into_builder().build_global().map_err(Box::from)
785	}
786	
787	impl<S> fmt::Debug for ThreadPoolBuilder<S> {
788	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
789	        let ThreadPoolBuilder {
790	            ref num_threads,
791	            ref use_current_thread,
792	            ref get_thread_name,
793	            ref panic_handler,
794	            ref stack_size,
795	            ref start_handler,
796	            ref exit_handler,
797	            spawn_handler: _,
798	            ref breadth_first,
799	        } = *self;
800	
801	        // Just print `Some(<closure>)` or `None` to the debug
802	        // output.
803	        struct ClosurePlaceholder;
804	        impl fmt::Debug for ClosurePlaceholder {
805	            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
806	                f.write_str("<closure>")
807	            }
808	        }
809	        let get_thread_name = get_thread_name.as_ref().map(|_| ClosurePlaceholder);
810	        let panic_handler = panic_handler.as_ref().map(|_| ClosurePlaceholder);
811	        let start_handler = start_handler.as_ref().map(|_| ClosurePlaceholder);
812	        let exit_handler = exit_handler.as_ref().map(|_| ClosurePlaceholder);
813	
814	        f.debug_struct("ThreadPoolBuilder")
815	            .field("num_threads", num_threads)
816	            .field("use_current_thread", use_current_thread)
817	            .field("get_thread_name", &get_thread_name)
818	            .field("panic_handler", &panic_handler)
819	            .field("stack_size", &stack_size)
820	            .field("start_handler", &start_handler)
821	            .field("exit_handler", &exit_handler)
822	            .field("breadth_first", &breadth_first)
823	            .finish()
824	    }
825	}
826	
827	#[expect(deprecated)]
828	impl fmt::Debug for Configuration {
829	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
830	        self.builder.fmt(f)
831	    }
832	}
833	
834	/// Provides the calling context to a closure called by `join_context`.
835	#[derive(Debug)]
836	pub struct FnContext {
837	    migrated: bool,
838	
839	    /// disable `Send` and `Sync`, just for a little future-proofing.
840	    _marker: PhantomData<*mut ()>,
841	}
842	
